files.content:
html {
  block-size: 100%;
}

body {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  min-inline-size: 360px;
  min-block-size: 100%;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
}

.page {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  inline-size: 100%;
  block-size: 100vh;
  font-family: serif;
  background-image: url(https://picsum.practicum-team.ru/random-image);
  background-position: center;
  background-size: cover;
}

.page__title {
  margin: 60px 0 0;
  color: #fff;
  font-family: 'Open Sans', sans-serif;
  font-weight: 600;
  font-size: 42px;
  line-height: 1.5;
}

img {
  inline-size: 50%;
}

@media (width <= 768px) {
  .page__title {
    font-size: 32px;
  }
}
